def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = {}
    for k, v in opponents_status.items():
        if v.get('alive'):
            alive[k] = v

    if not alive:
        return float(min(budget, 10.0))

    bob_prev_bid = None
    bob_budget = None
    eric_alive = False
    eric_prev_bid = None
    max_prev_bid = 0.0
    urgent_opp = 0

    for name, opp in alive.items():
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            if pbid > max_prev_bid:
                max_prev_bid = pbid
        if name == 'Bob':
            bob_prev_bid = pbid
            bob_budget = opp.get('budget', 0)
        if name == 'Eric':
            eric_alive = True
            eric_prev_bid = pbid
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1

    scarcity = supply <= 18
    abundant = supply >= 22

    need_now = False
    if hp <= 2 or no_water_days >= 1:
        need_now = True

    if need_now:
        bid = 62.0
        if bob_prev_bid is not None and bob_prev_bid >= 80:
            bid = max(bid, min(95.0, bob_prev_bid + 3.0))
        return float(min(budget, bid))

    if scarcity:
        if bob_prev_bid is not None and bob_prev_bid >= 100:
            bid = 18.0
        elif bob_prev_bid is not None and bob_prev_bid >= 75:
            bid = 24.0
        else:
            bid = 16.2 if eric_alive else 14.0
        if urgent_opp >= 2:
            bid += 2.0
    elif abundant:
        if bob_prev_bid is not None and bob_prev_bid >= 90:
            bid = 12.0
        else:
            bid = 8.0
    else:
        if bob_prev_bid is not None and bob_prev_bid >= 90:
            bid = 16.5
        elif bob_prev_bid is not None and bob_prev_bid >= 70:
            bid = 18.5
        else:
            bid = 12.5 if eric_alive else 10.0

    if bob_budget is not None and bob_budget < 80:
        bid = min(bid, 17.0)
    if hp >= 8 and budget < 120:
        bid = min(bid, 12.0)
    if hp <= 4:
        bid = max(bid, 20.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents only
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Estimate opponent aggressiveness
    highest_prev = max(prev_bids) if prev_bids else 0.0
    lowest_prev = min(prev_bids) if prev_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # If I'm in danger, bid more aggressively.
    if my_hp <= 2:
        base = DAILY_SALARY * 0.9
    elif my_hp <= 4:
        base = DAILY_SALARY * 0.65
    else:
        # Otherwise, exploit low-bid behavior like Eric (~15 avg)
        # by bidding slightly above the low end unless Alex was very high.
        if highest_prev >= DAILY_SALARY * 0.85:
            # Alex likely bidding to secure; we can still try to win with a mid bid.
            base = max(DAILY_SALARY * 0.55, lowest_prev + 10.0)
        else:
            base = max(DAILY_SALARY * 0.35, lowest_prev + 8.0)

    # Supply scaling: when supply is higher, we can lower bids.
    # supply range is [15,25]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    t = 0.0 if t < 0.0 else (1.0 if t > 1.0 else t)

    # Higher supply => bid slightly less
    base = base * (1.0 - 0.12 * t)

    # Ensure we don't bid more than budget
    bid = max(0.0, min(my_budget, base))

    # On early days, slightly more conservative to preserve budget for later pressure.
    if day <= 3:
        bid *= 0.95

    return float(bid)

